using System.Text.Json;using Microsoft.AspNetCore.Http;using Microsoft.EntityFrameworkCore;using SRECommerce.BuildingBlocks.Contracts;using SRECommerce.BuildingBlocks.Infrastructure;using SRECommerce.Order.Application;using SRECommerce.Order.Domain;
namespace SRECommerce.Order.Infrastructure;
public sealed class OrderRepository(OrderDbContext db,ModuleScope scope,IHttpContextAccessor contexts,ServiceSpec service):IOrderRepository
{
 public async Task<T> Transaction<T>(Func<CancellationToken,Task<T>> action,CancellationToken ct){await using var transaction=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);var result=await action(ct);await transaction.CommitAsync(ct);return result;}
 public Task<CheckoutIntent[]> Due(DateTimeOffset now,CancellationToken ct)=>db.Intents.Where(i=>(i.State==CheckoutState.AwaitingProof||i.State==CheckoutState.Processing||i.State==CheckoutState.Compensating)&&i.NextAttemptAt<=now&&(i.LeaseUntil==null||i.LeaseUntil<=now)).OrderBy(i=>i.NextAttemptAt).ThenBy(i=>i.Id).Take(5).ToArrayAsync(ct);
 public async Task<CheckoutIntent?> FreshIntent(Guid id,CancellationToken ct){var value=await Intent(id,ct);if(value is not null)await db.Entry(value).ReloadAsync(ct);return value;}
 public Task<OrderFulfillment[]> PendingFulfillments(DateTimeOffset now,CancellationToken ct)=>db.Fulfillments.Where(f=>f.Status==FulfillmentStatus.Requested&&f.NextAttemptAt<=now).OrderBy(f=>f.CreatedAt).Take(3).ToArrayAsync(ct);
 public Task<OrderReturn[]> PendingReturns(DateTimeOffset now,CancellationToken ct)=>db.Returns.Where(r=>(r.Status==ReturnStatus.Receiving||r.Status==ReturnStatus.RefundPending)&&r.NextAttemptAt<=now).OrderBy(r=>r.CreatedAt).Take(3).ToArrayAsync(ct);
 public Task<SalesOrder[]> PendingCOD(CancellationToken ct)=>db.Orders.Include(o=>o.Items).Where(o=>o.Status==OrderStatus.Delivered&&o.PaymentState==PaymentState.CashOnDelivery).OrderBy(o=>o.CreatedAt).Take(3).ToArrayAsync(ct);
 public Task<OrderPolicy?> Policy(CancellationToken ct)=>db.Policies.SingleOrDefaultAsync(ct);public Task<CheckoutIntent?> Intent(Guid id,CancellationToken ct)=>db.Intents.SingleOrDefaultAsync(i=>i.Id==id,ct);public Task<SalesOrder?> Order(Guid id,CancellationToken ct)=>db.Orders.Include(o=>o.Items).SingleOrDefaultAsync(o=>o.Id==id,ct);
 public async Task<(SalesOrder[] Items,int Total)> Orders(int page,OrderStatus? status,Guid? user,CancellationToken ct){var query=db.Orders.Include(o=>o.Items).AsQueryable();if(status is {} filter)query=query.Where(o=>o.Status==filter);if(user is {} owner)query=query.Where(o=>o.UserId==owner);var total=await query.CountAsync(ct);return(await query.OrderByDescending(o=>o.CreatedAt).ThenBy(o=>o.Id).Skip((page-1)*50).Take(50).ToArrayAsync(ct),total);}
 public Task<OrderReservation[]> Reservations(Guid order,CancellationToken ct)=>db.Reservations.Where(r=>r.OrderId==order).OrderBy(r=>r.Id).ToArrayAsync(ct);public Task<OrderOperation?> Operation(Guid id,CancellationToken ct)=>db.Operations.SingleOrDefaultAsync(o=>o.Id==id,ct);public Task<OrderStatusHistory[]> History(Guid order,CancellationToken ct)=>db.History.AsNoTracking().Where(h=>h.OrderId==order).OrderBy(h=>h.CreatedAt).ThenBy(h=>h.Id).ToArrayAsync(ct);
 public Task<OrderFulfillment?> Fulfillment(Guid id,CancellationToken ct)=>db.Fulfillments.SingleOrDefaultAsync(f=>f.Id==id,ct);public Task<OrderFulfillment[]> Fulfillments(Guid order,CancellationToken ct)=>db.Fulfillments.Where(f=>f.OrderId==order).OrderBy(f=>f.CreatedAt).ToArrayAsync(ct);
 public Task<OrderReturn?> Return(Guid id,CancellationToken ct)=>db.Returns.SingleOrDefaultAsync(r=>r.Id==id,ct);public Task<OrderReturn[]> Returns(Guid order,CancellationToken ct)=>db.Returns.Where(r=>r.OrderId==order).OrderBy(r=>r.CreatedAt).ToArrayAsync(ct);public Task<OrderExchange?> Exchange(Guid id,CancellationToken ct)=>db.Exchanges.SingleOrDefaultAsync(e=>e.Id==id,ct);public Task<OrderExchange[]> Exchanges(Guid order,CancellationToken ct)=>db.Exchanges.Where(e=>e.OrderId==order).OrderBy(e=>e.CreatedAt).ToArrayAsync(ct);
 public Task<OrderImport?> Import(Guid id,CancellationToken ct)=>db.Imports.SingleOrDefaultAsync(i=>i.Id==id,ct);public void Add<T>(T value)where T:class=>db.Add(value);public void Version(SRECommerce.BuildingBlocks.Kernel.IVersionedRecord value,string expected)=>db.ExpectedVersion(value,expected);
 public async Task<Guid?> NotificationOrder(Guid eventId,string type,CancellationToken ct)
 {
  var json=await db.Outbox.AsNoTracking().Where(x=>x.Id==eventId&&x.Type==type).Select(x=>x.Envelope).SingleOrDefaultAsync(ct);
  return json is null?null:ContractJson.Read<EventEnvelope>(json).Data.Deserialize<OrderNoticeResource>(ContractJson.Strict)?.OrderId;
 }
 public void EmitNotice(int kind,Guid order)=>db.Emit(scope,service,contexts,OrderNoticesContract.Types[kind],new OrderNoticeResource(order));
 public Task<bool> VerifiedPurchase(Guid user,Guid product,CancellationToken ct)=>db.Orders.AsNoTracking()
  .AnyAsync(o=>o.UserId==user&&!o.Historical&&o.Status!=OrderStatus.Cancelled&&o.Status!=OrderStatus.Failed&&o.Items.Any(i=>i.ProductId==product&&i.Delivered>i.Returned),ct);
 public async Task Commit(string action,Guid resource,object? integrationEvent,CancellationToken ct){db.Record(scope,contexts,action,resource.ToString());if(integrationEvent is not null)db.Emit(scope,service,contexts,action+".v1",integrationEvent);await db.SaveChangesAsync(ct);}
}
